// alwaysOutputData emits one placeholder {} item when zero companies match
// (e.g. everything archived) — without filtering it out, allIncomingItems
// would respond with [{}] instead of a real [], or (without
// alwaysOutputData at all) a 0-byte body the frontend can't parse. Same
// bug/fix as contacts-show-to-UI.json's Ensure Array Response.
const rows = $input.all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
return [{ json: { rows } }];

const headers = $input.first().json.headers || {};
const authHeader = headers['authorization'] || headers['Authorization'] || '';
const token = authHeader.replace('Bearer ', '').trim();

const match = token.match(/^token_(\d+)_(\d+)$/);
if (!match) throw new Error('Invalid or missing session token.');

return [{ json: { requesterId: parseInt(match[1], 10) } }];

