const requesterId = $('Parse Token: update-companies').first().json.requesterId;
const before = $('Postgres: Capture Before Owner: update-companies').first().json;
const after = $('Postgres: Update Company').first().json;
const oldOwnerId = before ? before.owner_id : null;
const newOwnerId = after.owner_id;
// Only notify on an actual reassignment to someone else — not a
// no-op resave of the same owner, and not an admin assigning themselves.
const notify = !!newOwnerId && newOwnerId !== oldOwnerId && newOwnerId !== requesterId;
const dmKey = notify ? [requesterId, newOwnerId].sort((a, b) => a - b).join('-') : null;
return [{ json: { notify, dmKey, requesterId, ownerId: newOwnerId, companyId: after.id, companyName: after.name || 'a company' } }];

