SELECT (
  SELECT id FROM companies
  WHERE is_archived = false
    AND (
      LOWER(name) = LOWER($1)
      OR ($2 <> '' AND LOWER(website) = LOWER($2))
    )
  LIMIT 1
) AS duplicate_id;

