const result = $input.first();
if (result && result.json && result.json.duplicate_id) {
  throw new Error('A company with this name or website is already in the database.');
}
return [{ json: {} }];

const requester = $('Look Up Requester: update-companies').first().json;
const body = $('Webhook: update-companies').first().json.body || {};

if (!requester.id || !requester.active) throw new Error('Invalid session.');

const companyId = parseInt(body.id, 10);
if (!Number.isInteger(companyId)) throw new Error('"id" must be an integer.');

// Only a field actually present in the request body gets written —
// an omitted key leaves that column untouched (true partial-update
// semantics, same as contacts-update.json's Parse Token & Payload).
function field(name) {
  if (body[name] === undefined) return undefined;
  return (body[name] === null || body[name] === '') ? null : body[name];
}
function intField(name) {
  const v = field(name);
  if (v === undefined) return undefined;
  if (v === null || v === '') return null;
  const n = parseInt(v, 10);
  return Number.isInteger(n) ? n : null;
}

const textColumns = [
  'name', 'website', 'industry', 'city', 'state', 'country', 'phone',
  'street_address', 'zip_code', 'tier', 'annual_revenue', 'employee_count',
  'territory', 'account_status', 'account_health',
];
const intColumns = ['owner_id', 'parent_company_id', 'se_user_id', 'csm_user_id'];

const setClauses = [];
const queryParams = [];
let idx = 1;

for (const col of textColumns) {
  const v = field(col);
  if (v === undefined) continue;
  setClauses.push(`${col} = $${idx}`);
  queryParams.push(v);
  idx++;
}
for (const col of intColumns) {
  const v = intField(col);
  if (v === undefined) continue;
  setClauses.push(`${col} = $${idx}`);
  queryParams.push(v);
  idx++;
}

if (setClauses.length === 0) throw new Error('No fields to update.');

setClauses.push('updated_at = now()');

const sqlQuery = `
  UPDATE companies SET
    ${setClauses.join(',\n    ')}
  WHERE id = $${idx} AND ($${idx + 1} = 'admin' OR owner_id = $${idx + 2})
  RETURNING id, name, owner_id;
`;

queryParams.push(companyId, requester.role, requester.id);

return [{ json: { sqlQuery, queryParams } }];

